 private void addToMy(JSONObject song){String cookie=playlists.cookie();executor.execute(()->{try{JSONObject data=playlists.lists(cookie);JSONArray items=data.getJSONArray("items");runOnUiThread(()->{if(isDestroyed())return;if(items.length()<=1){saveMySong(song,data,items.optJSONObject(0),cookie);return;}String[] names=new String[items.length()];for(int i=0;i<names.length;i++)names[i]=items.optJSONObject(i).optString("title");new AlertDialog.Builder(this).setTitle("재생목록에 담기").setItems(names,(d,index)->saveMySong(song,data,items.optJSONObject(index),cookie)).setNegativeButton("취소",null).show();});}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"재생목록을 불러오지 못했습니다. 연결과 로그인을 확인해 주세요.",Toast.LENGTH_LONG).show());}});}
 private void saveMySong(JSONObject song,JSONObject data,JSONObject chosen,String cookie){executor.execute(()->{try{if(chosen==null)playlists.add(song.optString("key"),cookie);else playlists.addTo(data,chosen,song.optString("key"),cookie);runOnUiThread(()->Toast.makeText(this,"재생목록에 담았습니다.",Toast.LENGTH_SHORT).show());}catch(Exception e){runOnUiThread(()->Toast.makeText(this,e instanceof NativePlaylistRepository.PlaylistException?e.getMessage():"저장하지 못했습니다. 다시 열어 주세요.",Toast.LENGTH_LONG).show());}});}
 private void playPlaylist(JSONArray keys){List<MediaItem> items=new ArrayList<>();if(keys!=null)for(int i=0;i<keys.length();i++){String key=keys.optString(i);for(JSONObject song:songs)if(key.equals(song.optString("key"))&&playable(song)){items.add(mediaItem(song));break;}}startNative(items,0);}
